import bisect

def length_of_lis(nums):
    tails = []
    for n in nums:
        idx = bisect.bisect_left(tails, n)                   # find insertion point
        if idx == len(tails):
            tails.append(n)                                        # extends the longest subsequence
        else:
            tails[idx] = n                                          # improves (lowers) a tail value
    return len(tails)

