import java.util.*;

public class Main {
    static int lengthOfLIS(int[] nums) {
        List<Integer> tails = new ArrayList<>();
        for (int n : nums) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {                                          // binary search insertion point
                int mid = (lo + hi) / 2;
                if (tails.get(mid) < n) lo = mid + 1; else hi = mid;
            }
            if (lo == tails.size()) tails.add(n);                        // extends the longest subsequence
            else tails.set(lo, n);                                          // improves (lowers) a tail value
        }
        return tails.size();
    }
}

