int lengthOfLIS(vector<int>& nums) {
    vector<int> tails;
    for (int n : nums) {
        auto it = lower_bound(tails.begin(), tails.end(), n);        // binary search insertion point
        if (it == tails.end()) tails.push_back(n);                     // extends the longest subsequence
        else *it = n;                                                     // improves (lowers) a tail value
    }
    return tails.size();
}
